import type { Comment, Issue, Label, Milestone } from '../types'

/** Where a repository lives on a Forgejo/Gitea host. */
export type RepoRef = {
  host: string
  owner: string
  repo: string
  webBase: string
  apiBase: string
}

/**
 * Reads a git remote URL in any of its spellings: scp-like
 * (`git@host:owner/repo.git`), `ssh://`, `https://` (with or without a port or
 * credentials). The API is assumed on https at the same host; `apiOverride`
 * replaces it where the SSH host is not the web host.
 */
export function parseRemote(url: string, apiOverride = ''): RepoRef | null {
  const trimmed = url.trim()
  let host: string | undefined
  let path: string | undefined
  const scp = /^(?:[^@/\s]+@)?([^:/\s]+):(?!\/\/)(.+)$/.exec(trimmed)
  const full = /^(?:ssh|https?|git):\/\/(?:[^@/\s]+@)?([^/:\s]+)(?::\d+)?\/(.+)$/.exec(trimmed)
  if (full) [, host, path] = full
  else if (scp) [, host, path] = scp
  if (!host || !path) return null
  const parts = path.replace(/\.git\/?$/, '').replace(/\/$/, '').split('/')
  const repo = parts.pop()
  const owner = parts.pop()
  if (!owner || !repo) return null
  const webBase = `https://${host}`
  const apiBase = apiOverride ? apiOverride.replace(/\/+$/, '') : `${webBase}/api/v1`
  return { host, owner, repo, webBase, apiBase }
}

/** The secrets-file key holding the token for `host`: `FORGEJO_TOKEN_GIT_EXAMPLE_ORG`. */
export function tokenKey(host: string): string {
  return `FORGEJO_TOKEN_${host.toUpperCase().replace(/[^A-Z0-9]/g, '_')}`
}

/** Parses `KEY=value` lines (comments, blank lines, `export`, quotes allowed). */
export function parseEnv(text: string): Map<string, string> {
  const out = new Map<string, string>()
  for (const line of text.split('\n')) {
    const m = /^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*?)\s*$/.exec(line)
    if (!m || !m[1]) continue
    let value = m[2] ?? ''
    if (/^(['"]).*\1$/.test(value)) value = value.slice(1, -1)
    out.set(m[1], value)
  }
  return out
}

/**
 * The token fgj keeps for `host` in its config.yaml
 * (`hosts: { <host>: { token } }`), read without a YAML library.
 */
export function fgjToken(yaml: string, host: string): string | undefined {
  let inHost = false
  let hostIndent = -1
  for (const line of yaml.split('\n')) {
    if (!line.trim() || line.trim().startsWith('#')) continue
    const indent = line.length - line.trimStart().length
    const key = /^\s*([^:\s]+):\s*(.*)$/.exec(line)
    if (!key) continue
    if (inHost && indent <= hostIndent) inHost = false
    if (key[1] === host && !key[2]) {
      inHost = true
      hostIndent = indent
    } else if (inHost && key[1] === 'token' && key[2]) {
      return key[2].replace(/^(['"])(.*)\1$/, '$2')
    }
  }
  return undefined
}

/** Where a token was found, for the pane to say (never the token itself). */
export type TokenSource = 'secrets' | 'fgj'

/**
 * The token for `host`, first match wins: the claude-mods secrets file's
 * host-bound key, then fgj's entry for that host. Never a token keyed to
 * another host, so a repo on one forge cannot leak another forge's token.
 */
export function pickToken(
  host: string,
  secretsText: string | null,
  fgjYaml: string | null,
): { token: string; source: TokenSource } | null {
  const fromSecrets = secretsText ? parseEnv(secretsText).get(tokenKey(host)) : undefined
  if (fromSecrets) return { token: fromSecrets, source: 'secrets' }
  const fromFgj = fgjYaml ? fgjToken(fgjYaml, host) : undefined
  if (fromFgj) return { token: fromFgj, source: 'fgj' }
  return null
}

type ApiIssue = {
  number: number
  title: string
  body?: string
  state: string
  comments: number
  updated_at: string
  html_url: string
  user?: { login?: string }
  labels?: { name: string; color: string }[]
  milestone?: { title?: string } | null
  pull_request?: unknown
}

function list<T>(json: string, what: string): T[] {
  const raw = JSON.parse(json) as unknown
  if (!Array.isArray(raw)) throw new Error(`${what} is not a list`)
  return raw as T[]
}

const hex = (c: string) => `#${c.replace(/^#/, '')}`

/** Narrows the API's issue list to what the pane draws; pull requests are left out. */
export function toIssues(json: string): Issue[] {
  return list<ApiIssue>(json, 'issue list')
    .filter(i => !i.pull_request)
    .map(i => ({
      number: i.number,
      title: i.title,
      body: i.body ?? '',
      state: i.state === 'closed' ? 'closed' : 'open',
      comments: i.comments,
      updatedAt: i.updated_at,
      url: i.html_url,
      author: i.user?.login ?? '',
      labels: (i.labels ?? []).map(l => ({ name: l.name, color: hex(l.color) })),
      milestone: i.milestone?.title ?? null,
    }))
}

export function toLabels(json: string): Label[] {
  return list<{ id: number; name: string; color: string; exclusive?: boolean; description?: string }>(json, 'label list').map(
    l => ({ id: l.id, name: l.name, color: hex(l.color), exclusive: Boolean(l.exclusive), description: l.description ?? '' }),
  )
}

export function toMilestones(json: string): Milestone[] {
  return list<{ id: number; title: string; state?: string; open_issues?: number; closed_issues?: number }>(json, 'milestone list').map(m => ({
    id: m.id,
    title: m.title,
    state: m.state === 'closed' ? 'closed' : 'open',
    open: m.open_issues ?? 0,
    closed: m.closed_issues ?? 0,
  }))
}

export function toComments(json: string): Comment[] {
  return list<{ user?: { login?: string }; body?: string; created_at: string }>(json, 'comment list').map(c => ({
    author: c.user?.login ?? '',
    body: c.body ?? '',
    createdAt: c.created_at,
  }))
}

/** Splits a scoped label (`kind/bug`, `area/ui/menu`) at its last slash, as Forgejo does. */
export function scopeOf(name: string): { scope: string | null; leaf: string } {
  const at = name.lastIndexOf('/')
  return at > 0 && at < name.length - 1 ? { scope: name.slice(0, at), leaf: name.slice(at + 1) } : { scope: null, leaf: name }
}

/**
 * Turns bare `#123` references into links to the issue page, outside code
 * spans and fences, so the pane can catch a press on one and open it in place.
 */
export function linkifyRefs(markdown: string, issueBase: string): string {
  return markdown
    .split(/(```[\s\S]*?(?:```|$))/)
    .map((block, i) =>
      i % 2 === 1
        ? block
        : block
            .split(/(`[^`\n]*`)/)
            .map((part, j) =>
              j % 2 === 1 ? part : part.replace(/(^|[^\w&#\[\/])#(\d+)\b/g, (_, pre: string, n: string) => `${pre}[#${n}](${issueBase}/${n})`),
            )
            .join(''),
    )
    .join('')
}

/** "3d", "5h", "just now": how long ago `iso` was, from `now` (ms). */
export function ago(iso: string, now: number): string {
  const s = Math.max(0, Math.round((now - Date.parse(iso)) / 1000))
  if (s < 60) return 'now'
  const units: [number, string][] = [[31_536_000, 'y'], [2_592_000, 'mo'], [86_400, 'd'], [3_600, 'h'], [60, 'm']]
  for (const [size, unit] of units) if (s >= size) return `${Math.floor(s / size)}${unit}`
  return 'now'
}

files.hooks/guard.ts:
/**
 * Whether a tool call by the model reaches into the claude-mods secrets
 * folder. A mod reads that folder itself; the model has no reason to, and a
 * stray `cat` or `grep -r ~/.config` would put a token in the transcript.
 *
 * Bash is matched on the command text, so a determined command can get past
 * it; it is there to stop the accidental reads.
 */
export function touchesSecrets(
  tool: string,
  input: Record<string, unknown>,
  secretsDir: string,
  home: string,
): boolean {
  const dir = secretsDir.replace(/\/+$/, '')
  const spellings = [dir]
  if (home && dir.startsWith(`${home}/`)) {
    const rest = dir.slice(home.length)
    spellings.push(`~${rest}`, `$HOME${rest}`, `\${HOME}${rest}`)
  }
  // The folder itself or anything in it: the spelling ends at a path end, a
  // slash, or a character no path segment holds (a quote, space, `;`, `|`, ...).
  const pattern = new RegExp(`(?:${spellings.map(escape).join('|')})(?=$|[/\\s'"\`;|&)<>])`)
  const hits = (text: unknown) => typeof text === 'string' && pattern.test(text)

  switch (tool) {
    case 'Read':
    case 'Write':
    case 'Edit':
      return hits(input.file_path)
    case 'Grep':
    case 'Glob':
      // A search rooted above the folder is let through: blocking those would
      // stop every search of ~/.config. Only a search aimed at it is refused.
      return hits(input.path) || hits(input.pattern)
    case 'Bash': {
      // A heredoc's body is text on its way somewhere (a file, a commit
      // message), not a path being opened; only the command itself counts.
      const command = stripHeredocs(String(input.command ?? ''))
      const relative = home && dir.startsWith(`${home}/`) ? dir.slice(home.length + 1) : null
      return hits(command) || (relative !== null && new RegExp(`(^|[\\s'"=])${escape(relative)}\\b`).test(command))
    }
    default:
      return false
  }
}

/** The command with every heredoc body (`<<EOF` … `EOF`, any quoting or `<<-`) taken out. */
export function stripHeredocs(command: string): string {
  const lines = command.split('\n')
  const out: string[] = []
  const pending: string[] = []
  for (const line of lines) {
    if (pending.length > 0) {
      if (line.replace(/^\t+/, '') === pending[0]) pending.shift()
      continue
    }
    out.push(line)
    for (const m of line.matchAll(/<<-?\s*(['"]?)([A-Za-z_][A-Za-z0-9_]*)\1/g)) pending.push(m[2]!)
  }
  return out.join('\n')
}

function escape(text: string): string {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

files.hooks/triage.ts:
import type { Label, Milestone, NewIssue } from '../types'

/**
 * `selected` with `name` toggled. Turning on a label from an exclusive scope
 * (`kind/bug` where `kind/` is exclusive) turns its siblings off, as Forgejo
 * itself only keeps one per such scope.
 */
export function toggleScoped(selected: string[], name: string, labels: Label[]): string[] {
  if (selected.includes(name)) return selected.filter(s => s !== name)
  const at = name.lastIndexOf('/')
  const scope = at > 0 ? name.slice(0, at + 1) : null
  const exclusive = scope !== null && labels.some(l => l.exclusive && l.name.startsWith(scope))
  const kept = exclusive && scope ? selected.filter(s => !s.startsWith(scope)) : selected
  return [...kept, name]
}

/** The ids of the labels named, in the repo's label list; unknown names are skipped. */
export function labelIds(names: string[], labels: Label[]): number[] {
  const byName = new Map(labels.map(l => [l.name, l.id]))
  return names.map(n => byName.get(n)).filter((id): id is number => id !== undefined)
}

/** The id of the milestone titled `title`, 0 for none (what the API takes to clear it). */
export function milestoneId(title: string | null, milestones: Milestone[]): number {
  return title ? (milestones.find(m => m.title === title)?.id ?? 0) : 0
}

export type TriageRules = {
  requireMilestone: boolean
  /** One of these labels must be set; empty for no such rule. */
  requireLabelFrom: string[]
}

/** Parses the comma-separated `requireLabelFrom` setting. */
export function parseLabelList(text: string): string[] {
  return text
    .split(',')
    .map(s => s.trim())
    .filter(Boolean)
}

/** Why `draft` cannot be filed yet, worded for the form, or null when it can. */
export function newIssueProblem(draft: NewIssue, rules: TriageRules): string | null {
  if (!draft.title.trim()) return 'Give the issue a title.'
  if (rules.requireMilestone && !draft.milestone) return 'Pick a milestone: every issue needs one here.'
  if (rules.requireLabelFrom.length > 0 && !draft.labels.some(l => rules.requireLabelFrom.includes(l))) {
    return `Pick one of: ${rules.requireLabelFrom.join(', ')}.`
  }
  return null
}

